import requests

from bs4 import BeautifulSoup
from urllib.parse import urljoin, urlparse


class BrokenLinkChecker:

    def __init__(self, url: str, html: str):

        self.url = url
        self.soup = BeautifulSoup(html, "html.parser")

    def extract_links(self):

        links = set()

        for tag in self.soup.find_all("a", href=True):

            href = tag.get("href", "").strip()

            if not href:
                continue

            absolute_url = urljoin(self.url, href)

            links.add(absolute_url)

        return list(links)

    def categorize_links(self):

        internal = []
        external = []

        base_domain = urlparse(self.url).netloc

        for link in self.extract_links():

            domain = urlparse(link).netloc

            if domain == base_domain:

                internal.append(link)

            else:

                external.append(link)

        return {
            "internal": internal,
            "external": external
        }

    def check_link_status(self, url):

        try:

            response = requests.get(
                url,
                timeout=10,
                allow_redirects=True,
                headers={
                    "User-Agent": "Mozilla/5.0"
                }
            )

            return response.status_code

        except requests.RequestException:

            return None

    def find_broken_links(self):

        broken_links = []

        categorized = self.categorize_links()

        all_links = (
            categorized["internal"] +
            categorized["external"]
        )

        for link in all_links:

            status = self.check_link_status(link)

            if status is None or status >= 400:

                broken_links.append({
                    "url": link,
                    "status": status
                })

        return broken_links

    def get_summary(self):

        categorized = self.categorize_links()

        broken_links = self.find_broken_links()

        total_links = (
            len(categorized["internal"]) +
            len(categorized["external"])
        )

        return {

            "total_links": total_links,

            "internal_links": len(
                categorized["internal"]
            ),

            "external_links": len(
                categorized["external"]
            ),

            "broken_links": len(
                broken_links
            ),

            "details": broken_links
        }

"""
Website Crawler

Responsible for downloading webpages and extracting
basic website information.

This module DOES NOT calculate SEO scores.
"""

import time

import requests

from config import Config
from utils.validators import validate_url
from services.seo_checker import SEOAnalyzer


class WebsiteCrawler:

    def __init__(self):
        self.headers = Config.HEADERS
        self.timeout = Config.REQUEST_TIMEOUT

    def crawl(self, url: str) -> dict:

        if not validate_url(url):
            return {
                "success": False,
                "message": "Invalid URL"
            }

        try:
            start = time.perf_counter()

            response = requests.get(
                url,
                headers=self.headers,
                timeout=self.timeout,
                allow_redirects=True
            )

            response.raise_for_status()

            end = time.perf_counter()

            seo = SEOAnalyzer(response.text)
            seo_data = seo.analyze()

            return {
                "success": True,
                "url": response.url,
                "status_code": response.status_code,
                "response_time": round(end - start, 3),
                **seo_data,
                "message": "Website crawled successfully."
            }

        except requests.exceptions.RequestException as e:
            return {
                "success": False,
                "message": str(e)
            }

import requests


class PageSpeedAnalyzer:

    BASE_URL = "https://www.googleapis.com/pagespeedonline/v5/runPagespeed"

    def __init__(self, url: str, api_key: str):

        self.url = url
        self.api_key = api_key

    def analyze(self):

        params = {
            "url": self.url,
            "key": self.api_key,
            "category": [
                "performance",
                "accessibility",
                "best-practices",
                "seo"
            ]
        }

        try:

            response = requests.get(
                self.BASE_URL,
                params=params,
                timeout=30
            )

            response.raise_for_status()

            data = response.json()

            categories = data["lighthouseResult"]["categories"]

            audits = data["lighthouseResult"]["audits"]

            return {

                "performance": int(
                    categories["performance"]["score"] * 100
                ),

                "accessibility": int(
                    categories["accessibility"]["score"] * 100
                ),

                "best_practices": int(
                    categories["best-practices"]["score"] * 100
                ),

                "seo": int(
                    categories["seo"]["score"] * 100
                ),

                "largest_contentful_paint":
                    audits["largest-contentful-paint"]["displayValue"],

                "first_contentful_paint":
                    audits["first-contentful-paint"]["displayValue"],

                "speed_index":
                    audits["speed-index"]["displayValue"],

                "total_blocking_time":
                    audits["total-blocking-time"]["displayValue"],

                "cumulative_layout_shift":
                    audits["cumulative-layout-shift"]["displayValue"]
            }

        except requests.RequestException as e:

            return {

                "error": str(e)
            }

import csv
